//! Shared resource projection; scoped reads retain every binding and physical primary.
use rusqlite::{Connection,OptionalExtension};
use serde_json::{json,Value};
use crate::{ApiError,editions,automatch};
pub fn rows(c:&Connection,work_id:Option<&str>)->Result<Vec<Value>,ApiError>{project(c,work_id,None)}
pub fn selected(c:&Connection,ids:&[String])->Result<Vec<Value>,ApiError>{if ids.len()>60{return Err(ApiError("Too many resources".into()));}let encoded=serde_json::to_string(ids).map_err(|e|ApiError(e.to_string()))?;project(c,None,Some(&encoded))}
fn project(c:&Connection,work_id:Option<&str>,ids:Option<&str>)->Result<Vec<Value>,ApiError>{let select="SELECT r.id,r.title,r.relative_path,r.kind,r.work_id,r.release_label,count(f.id),coalesce(sum(f.size),0),rt.path,r.revision,r.root_id,coalesce(sum(f.availability='missing'),0),coalesce(sum(f.availability='unverified'),0),coalesce(sum(f.availability NOT IN ('present','missing','unverified')),0),pw.title FROM resources r JOIN roots rt ON r.root_id=rt.id LEFT JOIN works pw ON pw.id=r.work_id AND pw.merged_into IS NULL LEFT JOIN resource_files rf ON rf.resource_id=r.id LEFT JOIN files f ON f.id=rf.file_id GROUP BY r.id HAVING count(f.id)>0 ORDER BY r.title";let select=if ids.is_some(){select.replace(" GROUP BY"," WHERE r.id IN (SELECT value FROM json_each(?1)) GROUP BY")}else if work_id.is_some(){select.replace(" GROUP BY", " WHERE r.id IN (SELECT resource_id FROM resource_bindings WHERE work_id=?1) GROUP BY")}else{select.to_owned()};let mut s=c.prepare(&select)?;let values=ids.or(work_id).into_iter().collect::<Vec<_>>();let mut rows=s.query_map(rusqlite::params_from_iter(values),|r|Ok(json!({"id":r.get::<_,String>(0)?,"title":r.get::<_,String>(1)?,"path":r.get::<_,String>(2)?,"kind":r.get::<_,String>(3)?,"work_id":r.get::<_,Option<String>>(4)?,"release":r.get::<_,String>(5)?,"files":r.get::<_,i64>(6)?,"bytes":r.get::<_,i64>(7)?,"root_path":r.get::<_,String>(8)?,"revision":r.get::<_,i64>(9)?,"root_id":r.get::<_,String>(10)?,"missing":r.get::<_,i64>(11)?,"unverified":r.get::<_,i64>(12)?,"unknown":r.get::<_,i64>(13)?,"primary_work_title":r.get::<_,Option<String>>(14)?})))?.collect::<std::result::Result<Vec<_>,_>>()?;for row in &mut rows{row["bindings"]=json!(editions::bindings(&c,row["id"].as_str().unwrap())?);if row["work_id"].is_null(){let evidence:Option<String>=c.query_row("SELECT evidence FROM match_items WHERE resource_id=?1 AND state='review' ORDER BY rowid DESC LIMIT 1",[row["id"].as_str().unwrap()],|r|r.get(0)).optional()?;if let Some(e)=evidence{let v:Value=serde_json::from_str(&e).unwrap_or_default();row["auto_match_reason"]=json!(automatch::review_reason(&v));}}}Ok(rows)}